        cnt = 0
        spoon = [False] * N
        for p in P:
            match S[p]:
                case "L":
                    spoon[p] = True
                case "R":
                    if not spoon[(p + 1) % N]:
                        return 0
                    spoon[p] = True
                case "?":
                    if spoon[(p + 1) % N]:
                        cnt += 1
                    spoon[p] = True
        return pow(2, cnt)

    def countR():
        cnt = 0
        spoon = [False] * N
        for p in P:
            match S[p]:
                case "R":
                    spoon[(p + 1) % N] = True
                case "L":
                    if not spoon[p]:
                        return 0
                    spoon[(p + 1) % N] = True
                case "?":
                    if spoon[p]:
                        cnt += 1
                    spoon[(p + 1) % N] = True
        return pow(2, cnt)

    ans = 0
    for i in range(1 << S.count('?')):
        currentS = list(S)
        idx = 0
